<?php $c=settings('contact'); ?>
<section class="page-intro"><span class="eyebrow">LET’S TALK</span><h1><?= e($c['heading']) ?></h1><p><?= e($c['description']) ?></p></section><section class="section contact-layout"><div class="contact-details"><h2>A little conversation</h2><?php if($c['email']): ?><p><span class="eyebrow">EMAIL</span><a href="mailto:<?= e($c['email']) ?>"><?= e($c['email']) ?></a></p><?php endif ?><?php if($c['phone']): ?><p><span class="eyebrow">PHONE</span><?= e($c['phone']) ?></p><?php endif ?><?php if($c['address']||$c['city']): ?><p><span class="eyebrow">FIND US</span><?= nl2br(e($c['address'])) ?><br><?= e($c['city']) ?></p><?php endif ?><?php if($c['hours']): ?><p><span class="eyebrow">BUSINESS HOURS</span><?= e($c['hours']) ?></p><?php endif ?></div><?php if($c['form_enabled']): ?><form class="panel" action="/contact" method="post"><?= csrf_field() ?><h2>Send us a note</h2><label>Your name<input name="name" required maxlength="120" autocomplete="name"></label><label>Email<input type="email" name="email" required maxlength="254" autocomplete="email"></label><label>How can we help?<textarea name="message" required rows="6" maxlength="5000"></textarea></label><button class="button">Send message</button></form><?php endif ?></section>
